import * as THREE from './three.module.js';
import {loadGoldSrc} from './goldsrc-model.js';
export const IMPORTED_WEAPONS={
 champions21vandal:{name:'2021 冠军 · 狂徒',variants:{base:'重置材质'}},
 champions21knife:{name:'2021 冠军 · 爪刀',variants:{base:'冠军气息'}},
 champions24:{name:'2024 冠军 · 战刀',variants:{base:'二级',level1:'一级',aura:'冠军气息',plain:'无气息',shatter:'金色破碎'}},
 kuronami:{name:'黑波之刃',variants:{base:'蓝黑',purple:'紫色',white:'白色',black:'红黑'}},
 kuronamivandal:{name:'塑水宗 · 狂徒',variants:{base:'蓝色',purple:'紫色',white:'白色',black:'红黑'}}
};
export function importedSelection(id,prefs){const key=id==='knife'?prefs.knife:id==='vandal'?prefs.skin:null;if(!IMPORTED_WEAPONS[key])return null;const variant=key==='kuronami'?prefs.kuronamiVariant:prefs.importedVariants?.[key];return {key,variant:Object.hasOwn(IMPORTED_WEAPONS[key].variants,variant)?variant:'base'};}
const root=(key,variant)=>`./assets/imported/${key}/${variant}`;
const audioCache=new WeakMap();
async function soundBuffer(ctx,url){let cache=audioCache.get(ctx);if(!cache){cache=new Map();audioCache.set(ctx,cache);}if(!cache.has(url))cache.set(url,fetch(url).then(r=>{if(!r.ok)throw Error('Missing sound');return r.arrayBuffer();}).then(b=>ctx.decodeAudioData(b)).catch(e=>{cache.delete(url);throw e;}));return cache.get(url);}
export function sequenceFor(sequences,action){const name=action==='idle'?/^(idle|shezo|xeiv)/i:action==='shoot'?/^shoot/i:action==='slash1'?/^slash1/i:action==='slash2'?/^slash2/i:action==='stab'?/^stab/i:new RegExp('^'+action+'(?:$|_)','i');return sequences.find(s=>name.test(s.name)&&!/fast|copy/i.test(s.name))?.index??sequences.find(s=>name.test(s.name))?.index??0;}
// Absolute sequence sampling and a single cancellable event cursor.
export class NativeTimeline{
 constructor(sequences,onEvent=()=>{}){this.sequences=sequences;this.onEvent=onEvent;this.index=0;this.seconds=0;this.rate=1;this.playing=false;this.serial=0;this.lastFrame=-1;this.gameplay=false;}
 play(index,{rate=1,gameplay=false}={}){this.index=index;this.seconds=0;this.rate=rate;this.playing=true;this.gameplay=gameplay;this.lastFrame=-1;this.serial++;}
 seek(frame){this.seconds=Math.max(0,Math.min(this.sequence.frames-1,frame))/this.sequence.fps;this.playing=false;this.lastFrame=this.frame;this.serial++;}
 get sequence(){return this.sequences[this.index];}get frame(){return Math.min(this.sequence.frames-1,this.seconds*this.sequence.fps);}
 advance(dt){if(!this.playing)return;const s=this.sequence,end=s.duration,next=this.seconds+Math.max(0,dt)*this.rate,frame=Math.min(s.frames-1,next*s.fps);for(const e of s.events)if(e.frame>this.lastFrame&&e.frame<=frame)this.onEvent(e,this.serial);this.lastFrame=frame;this.seconds=Math.min(next,end);if(next>=end){if(s.loop&&end>0){this.seconds=0;this.lastFrame=-1;const rest=(next-end)/this.rate;if(rest>0)this.advance(rest);}else if(this.gameplay&&this.index!==sequenceFor(this.sequences,'idle')){const rest=(next-end)/this.rate;this.play(sequenceFor(this.sequences,'idle'),{gameplay:true});if(rest>0)this.advance(rest);}else this.playing=false;}}
}
export function createImportedWeapon(selection,{audio=()=>null,volume=()=>0,hands=null,onReady=()=>{},onError=()=>{}}={}){
 const {key,variant}=selection,base=root(key,variant),model=new THREE.Group();let rig=null,dead=false,timeline=null,metadata=[],shot=0,muzzle=null,muzzleFrames=[],request=0;const sources=new Set();let paused=false;
 function stopAudio(){request++;for(const x of sources){try{x.stop();}catch{}}sources.clear();}
 async function playSound(file,{offset=0,rate=timeline?.rate||1,serial=timeline?.serial,expectedIndex=timeline?.index}={}){const ctx=audio();if(!ctx||!file||!volume()||dead||paused)return false;const token=request,start=performance.now();try{const buffer=await soundBuffer(ctx,base+'/sound/'+file);if(dead||paused||token!==request||serial!==timeline?.serial||expectedIndex!==timeline?.index)return false;const pos=offset+(performance.now()-start)/1000*rate;if(pos>=buffer.duration)return false;const source=ctx.createBufferSource(),gain=ctx.createGain();source.buffer=buffer;source.playbackRate.value=rate;gain.gain.value=volume()*.8;source.connect(gain);gain.connect(ctx.destination);source.onended=()=>{sources.delete(source);source.disconnect();gain.disconnect();};sources.add(source);source.start(0,pos);return true;}catch{return false;}}
 function event(e,serial){const file=metadata[timeline.index]?.events.find(x=>x.frame===e.frame&&x.event===e.code&&x.options===e.options)?.sound;if(file)playSound(file,{serial,offset:Math.max(0,timeline.frame-e.frame)/timeline.sequence.fps});if(e.code===5001)shot=.09;}
 const art={model,imported:true,key,variant,get rig(){return rig;},get timeline(){return timeline;},get ready(){return !!rig;},duration(action){return timeline?.sequences[sequenceFor(timeline.sequences,action)].duration??(action==='draw'?1:action==='reload'?2.94:1);},action(action,rate=1,gameplay=true){paused=false;if(!timeline){art.pending={action,rate,gameplay};return;}stopAudio();const index=typeof action==='number'?action:sequenceFor(timeline.sequences,action);timeline.play(index,{rate,gameplay});rig.sample(index,0);if(key==='champions21knife'&&action==='inspect')playSound('inspect_1.wav');},seek(frame){stopAudio();timeline?.seek(frame);if(rig)rig.sample(timeline.index,timeline.frame);},update(dt){if(!rig||paused)return;timeline.advance(dt);rig.sample(timeline.index,timeline.frame);shot=Math.max(0,shot-dt);if(muzzle){muzzle.visible=shot>0;if(shot>0&&muzzleFrames.length)muzzle.material.map=muzzleFrames[Math.min(muzzleFrames.length-1,Math.floor((.09-shot)/.09*muzzleFrames.length))];} },shoot(heavy=false,side=0,aimed=false){art.action(key.includes('vandal')?(aimed?'zoom_shoot':'shoot'):heavy?'stab':side%2?'slash1':'slash2');if(key.includes('vandal')){shot=.09;playSound(key==='kuronamivandal'?'weapons/valorant/kuronamivandal/shoot.wav':null);}},setChampionAura(active){if(!rig)return;for(const mesh of rig.meshes)if(key==='champions21vandal'&&mesh.name==='1.bmp'||key==='champions21knife'&&mesh.name==='3.bmp')mesh.visible=active;},pause(){paused=true;stopAudio();},resume(){paused=false;const s=timeline?.sequence;if(!s)return;for(const e of metadata[timeline.index]?.events||[]){const at=e.frame/s.fps;if(e.sound&&at<=timeline.seconds)playSound(e.sound,{offset:timeline.seconds-at});}},stopAudio,preload(){const ctx=audio();if(ctx)for(const file of new Set(metadata.flatMap(s=>s.events.map(e=>e.sound)).filter(Boolean)))soundBuffer(ctx,base+'/sound/'+file).catch(()=>{});},dispose(){dead=true;stopAudio();rig?.dispose();muzzleFrames.forEach(t=>t.dispose());muzzle?.material.dispose();model.removeFromParent();}};
 art.readyPromise=Promise.all([loadGoldSrc(base+'/model.mdl'),fetch(base+'/sequences.json').then(r=>{if(!r.ok)throw Error('Missing sequence bank');return r.json();})]).then(async([parsed,events])=>{if(dead)return;metadata=events;rig=parsed.instantiate({hands});model.add(rig.model);timeline=new NativeTimeline(rig.sequences,event);const pending=art.pending;if(pending)art.action(pending.action,pending.rate,pending.gameplay);else art.action('idle',1,false);art.setChampionAura(false);onReady(art);art.preload();
  if(key==='kuronamivandal'){try{const data=await fetch(base+'/muzzle.json').then(r=>r.json());if(dead)return;const loader=new THREE.TextureLoader();muzzleFrames=data.frames.map(file=>{const t=loader.load(base+'/'+file);t.colorSpace=THREE.SRGBColorSpace;return t;});const attachment=rig.attachments[0];if(attachment){muzzle=new THREE.Sprite(new THREE.SpriteMaterial({map:muzzleFrames[0],transparent:true,blending:THREE.AdditiveBlending,depthWrite:false,toneMapped:false}));muzzle.position.fromArray(attachment.point);muzzle.scale.set(12,12,12);muzzle.visible=false;rig.bones[attachment.bone].add(muzzle);}}catch{/* Model remains usable if a separate sprite is absent. */}}
 }).catch(e=>{if(!dead)onError(e,art);});return art;
}
export async function createImportedFinisher(variant){const parsed=await loadGoldSrc(root('kuronamivandal',variant)+'/finisher.mdl'),rig=parsed.instantiate({world:true});return{...rig,duration:rig.sequences[0].duration,update(seconds){rig.sample(0,Math.min(rig.sequences[0].frames-1,seconds*rig.sequences[0].fps));}};}
const badgeRoot='./assets/imported/kuronamivandal/badge/kuronami';
export function importedBadgeMarkup(){return `<div class="imported-crest"><img data-layer="kill" src="${badgeRoot}/kill/1.png" alt=""><img data-layer="icon" src="${badgeRoot}/icons/skull.png" alt=""><img data-layer="particles1" src="${badgeRoot}/particles1/1.png" alt=""><img data-layer="particles2" src="${badgeRoot}/particles2/1.png" alt=""></div>`;}
export function updateImportedBadge(el,age,count=1,head=false){const n=Math.max(1,Math.min(5,count));for(const [layer,path]of Object.entries({kill:`kill/${n}`,icon:`icons/${head?'headshot':'skull'}`,particles1:`particles1/${Math.min(6,1+Math.floor(age*12))}`,particles2:`particles2/${Math.min(13,1+Math.floor(age*18))}`})){const img=el.querySelector(`[data-layer="${layer}"]`),src=badgeRoot+'/'+path+'.png';if(img&&img.getAttribute('src')!==src)img.src=src;}el.style.opacity=age>1.65?Math.max(0,(2.2-age)/.55):1;el.style.transform=`scale(${.82+.18*Math.min(1,age/.12)})`;}
